import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int p1 = Integer.parseInt(tokenizer.nextToken());
        int t1 = Integer.parseInt(tokenizer.nextToken());

        tokenizer = new StringTokenizer(reader.readLine());
        int p2 = Integer.parseInt(tokenizer.nextToken());
        int t2 = Integer.parseInt(tokenizer.nextToken());

        tokenizer = new StringTokenizer(reader.readLine());
        int h = Integer.parseInt(tokenizer.nextToken());
        int s = Integer.parseInt(tokenizer.nextToken());

        if (t1 > t2) {
            int tempP = p1;
            p1 = p2;
            p2 = tempP;
            int tempT = t1;
            t1 = t2;
            t2 = tempT;
        }

        int p = p1 + p2 - s;
        if (t1 == t2) {
            System.out.println(((h + p - 1) / p) * t1);
            return;
        }

        p1 -= s;
        p2 -= s;
        long ans = 1L << 63;
        long[] d1 = new long[20001];
        long[] d2 = new long[20001];
        for (int i = 0; i < 20001; i++) {
            d1[i] = ans;
            d2[i] = ans;
        }

        int e = 0, u = 0;
        int r1 = t1, r2 = t2;
        while (e < h) {
            if (r1 == r2) {
                e += p;
                u += r1;
                r1 = t1;
                r2 = t2;
                d1[e] = u;
                break;
            } else if (r1 < r2) {
                if (d2[e + p] > u + r2) {
                    d2[e + p] = u + r2;
                }
                e += p1;
                u += r1;
                r2 -= r1;
                r1 = t1;
            } else {
                if (d2[e + p] > u + r1) {
                    d2[e + p] = u + r1;
                }
                e += p2;
                u += r2;
                r1 -= r2;
                r2 = t2;
            }
            d1[e] = u;
        }

        long[] d3 = new long[h + 1];
        for (int i = 0; i <= h; i++) {
            d3[i] = ans;
        }
        d1[0] = d3[0] = 0;

        for (int i = e - 1; i > 0; i--) {
            if (d1[i] > d1[i + 1]) {
                d1[i] = d1[i + 1];
            }
        }

        List<int[]> v = new ArrayList<>();
        for (int i = 0; i <= e; i++) {
            if (d2[i] != ans) {
                v.add(new int[]{i, (int) d2[i]});
            }
        }

        for (int i = 0; i <= h; i++) {
            for (int[] pair : v) {
                int j = pair[0];
                int x = pair[1];
                int k = i + j;
                if (k > h) {
                    k = h;
                }
                if (d3[k] > d3[i] + x) {
                    d3[k] = d3[i] + x;
                }
            }
            if (ans > d3[i] + d1[h - i]) {
                ans = d3[i] + d1[h - i];
            }
        }

        System.out.println(ans);
    }
}

